class Room:

    RESERVED = "reserved"

    def __init__(self):
        self._guest = None

    # guests

    def guest_type(self):
        return self._guest

    def receive(self, a_guest_type):
        # Room Occupied
        if self._guest is not None or Room.RESERVED == self._guest:
            raise RuntimeError(Room.room_is_not_empty_error_description())
        else:
            self._guest = a_guest_type

    def receive_with_reservation(self, a_guest_type):
        # Room Reserved
        if Room.RESERVED == self._guest:
            self._guest = a_guest_type
        else:
            raise RuntimeError(Room.room_is_not_reserved_error_description())

    def reserve(self):
        # Room Occupied
        if self._guest is not None or Room.RESERVED == self._guest:
            raise RuntimeError(Room.room_is_not_empty_error_description())
        else:
            self._guest = Room.RESERVED

    # testing

    def is_available(self):
        return self._guest is None

    def is_occupied(self):
        return self._guest is not None or Room.RESERVED == self._guest

    def is_reserved(self):
        return Room.RESERVED == self._guest

    # accounting

    def profit_using_if_absent_guest_type(self, a_price_list, unknown_guest_type_block):
        # Room Available
        if self._guest is None:
            return 0

        # Room Reserved
        if Room.RESERVED == self._guest:
            return min(a_price_list.values()) // 2

        # Room Occupied
        if self._guest is not None or Room.RESERVED == self._guest:
            if self._guest in a_price_list:
                return a_price_list[self._guest]
            else:
                return unknown_guest_type_block()

    # error messages (class side)

    @staticmethod
    def room_is_not_empty_error_description():
        return "Room is not empty."

    @staticmethod
    def room_is_not_reserved_error_description():
        return "Room is not reserved."
from simshotels.room import Room


class Floor:

    def __init__(self):
        self._rooms = None
        self._prices = None

    # testing

    def is_available(self):
        return self.total_rooms() == self.total_rooms_available()

    # accessing

    def rooms(self):
        return self._rooms

    # accounting

    def total_losses(self):
        total = 0
        for room in self._rooms:
            if room.is_available():
                total = total + max(self._prices.values())

        return total

    def total_profits(self):
        total = 0
        for room in self._rooms:
            if room.is_occupied():
                room_total = room.profit_using_if_absent_guest_type(self._prices, lambda: Floor.signal_unknown_guest_type())
                total = total + room_total

        return total

    # setters

    def set_number_of_rooms(self, a_number_of_rooms):
        Floor.assert_is_positive_if_false(a_number_of_rooms, lambda: Floor.signal_number_of_rooms_must_be_positive())
        Floor.assert_is_integer_if_false(a_number_of_rooms, lambda: Floor.signal_number_of_rooms_must_be_integer())

        self.initialize_rooms_with(a_number_of_rooms)

    def set_prices(self, a_price_list):
        if len(a_price_list) == 0:
            Floor.signal_no_prices()

        for price in a_price_list.values():
            Floor.assert_is_positive_if_false(price, lambda: Floor.signal_price_must_be_positive())

        self.initialize_with(a_price_list)

    # totals

    def total_rooms(self):
        return len(self._rooms)

    def total_rooms_available(self):
        count = 0
        for room in self._rooms:
            if room.is_available():
                count = count + 1
        return count

    def total_rooms_occupied(self):
        count = 0
        for room in self._rooms:
            if room.is_occupied():
                count = count + 1
        return count

    def total_rooms_reserved(self):
        count = 0
        for room in self._rooms:
            if room.is_reserved():
                count = count + 1
        return count

    # initialization

    def initialize_rooms_with(self, a_number_of_rooms):
        self._rooms = []

        ix = 1
        while ix <= a_number_of_rooms:
            self._rooms.append(Room())
            ix = ix + 1

    def initialize_with(self, a_price_list):
        self._prices = a_price_list

    # assertions (class side)

    @staticmethod
    def assert_is_integer_if_false(a_number, signals_block):
        if not (isinstance(a_number, int) and not isinstance(a_number, bool)):
            signals_block()

    @staticmethod
    def assert_is_positive_if_false(a_number, signals_block):
        if not (a_number > 0):
            signals_block()

    # error messages (class side)

    @staticmethod
    def number_of_rooms_must_be_integer_error_description():
        return "Number of rooms must be integer"

    @staticmethod
    def number_of_rooms_must_be_positive_error_description():
        return "The number of rooms must be positive"

    @staticmethod
    def price_must_be_integer_error_description():
        return "Price must be integer"

    @staticmethod
    def price_must_be_positive_error_description():
        return "Price must be positive"

    @staticmethod
    def prices_list_cannot_be_empty_error_description():
        return "Prices List must not be empty"

    @staticmethod
    def unknown_guest_type_error_description():
        return "The guest type is unknown"

    # exceptions (class side)

    @staticmethod
    def signal_no_prices():
        raise RuntimeError(Floor.prices_list_cannot_be_empty_error_description())

    @staticmethod
    def signal_number_of_rooms_must_be_integer():
        raise RuntimeError(Floor.number_of_rooms_must_be_integer_error_description())

    @staticmethod
    def signal_number_of_rooms_must_be_positive():
        raise RuntimeError(Floor.number_of_rooms_must_be_positive_error_description())

    @staticmethod
    def signal_price_must_be_integer():
        raise RuntimeError(Floor.price_must_be_integer_error_description())

    @staticmethod
    def signal_price_must_be_positive():
        raise RuntimeError(Floor.price_must_be_positive_error_description())

    @staticmethod
    def signal_unknown_guest_type():
        raise RuntimeError(Floor.unknown_guest_type_error_description())
class Hotel:

    # initialization

    def __init__(self):
        self._floors = None
        self._available_rooms_count = 0

    # accounting

    def total_losses(self):
        acc = 0
        for floor in self._floors:
            acc = acc + floor.total_losses()

        return acc

    def total_profits(self):
        acc = 0
        for floor in self._floors:
            acc = acc + floor.total_profits()

        return acc

    # setters

    def set_floors(self, a_floors_collection):
        Hotel.assert_have_floors(a_floors_collection)

        self._floors = a_floors_collection

        self._available_rooms_count = self.total_rooms()

        return self

    # totals

    def total_rooms(self):
        acc = 0

        ix = 1
        while ix <= len(self._floors):
            floor = self._floors[ix - 1]

            jx = 1
            while jx <= len(floor.rooms()):
                acc = acc + 1

                jx = jx + 1

            ix = ix + 1

        return acc

    def total_rooms_available(self):
        return self._available_rooms_count

    def total_rooms_occupied(self):
        acc = 0

        ix = 1
        while ix <= len(self._floors):
            floor = self._floors[ix - 1]

            jx = 1
            while jx <= len(floor.rooms()):
                room = floor.rooms()[jx - 1]
                if room.is_occupied():
                    acc = acc + 1

                jx = jx + 1

            ix = ix + 1

        return acc

    def total_rooms_reserved(self):
        acc = 0

        ix = 1
        while ix <= len(self._floors):
            floor = self._floors[ix - 1]

            jx = 1
            while jx <= len(floor.rooms()):
                room = floor.rooms()[jx - 1]
                if room.is_reserved():
                    acc = acc + 1

                jx = jx + 1

            ix = ix + 1

        return acc

    # testing

    def is_empty(self):
        acc = True

        ix = 1
        while ix <= len(self._floors):
            floor = self._floors[ix - 1]

            jx = 1
            while jx <= len(floor.rooms()):
                room = floor.rooms()[jx - 1]
                acc = acc and room.is_available()

                jx = jx + 1

            ix = ix + 1

        return acc

    # guests

    def receive_at_floor_at_room(self, a_guest_type, a_floor_number, a_room_number):
        if a_floor_number < 1 or a_floor_number > len(self._floors):
            Hotel.signal_floor_number_does_not_exist()
        floor = self._floors[a_floor_number - 1]
        if a_room_number < 1 or a_room_number > len(floor.rooms()):
            Hotel.signal_room_number_does_not_exist()
        room = floor.rooms()[a_room_number - 1]

        room.receive(a_guest_type)

        self._available_rooms_count = self._available_rooms_count - 1

    def receive_with_reservation_at_floor_at_room(self, a_guest_type, a_floor_number, a_room_number):
        if a_floor_number < 1 or a_floor_number > len(self._floors):
            Hotel.signal_floor_number_does_not_exist()
        floor = self._floors[a_floor_number - 1]
        if a_room_number < 1 or a_room_number > len(floor.rooms()):
            Hotel.signal_room_number_does_not_exist()
        room = floor.rooms()[a_room_number - 1]

        room.receive_with_reservation(a_guest_type)

    def reserve_room_at_floor(self, a_room_number, a_floor_number):
        if a_floor_number < 1 or a_floor_number > len(self._floors):
            Hotel.signal_floor_number_does_not_exist()
        floor = self._floors[a_floor_number - 1]
        if a_room_number < 1 or a_room_number > len(floor.rooms()):
            Hotel.signal_room_number_does_not_exist()
        room = floor.rooms()[a_room_number - 1]

        room.reserve()

        self._available_rooms_count = self._available_rooms_count - 1

    # assertions (class side)

    @staticmethod
    def assert_have_floors(a_floors_collection):
        if len(a_floors_collection) == 0:
            Hotel.signal_no_floors()

    # error description (class side)

    @staticmethod
    def floor_number_does_not_exist_error_description():
        return "Floor number does not exist"

    @staticmethod
    def no_floors_error_description():
        return "Cannot have a Hotel without floors"

    @staticmethod
    def room_number_does_not_exist_error_description():
        return "Room number does not exist"

    # exceptions (class side)

    @staticmethod
    def signal_floor_number_does_not_exist():
        raise RuntimeError(Hotel.floor_number_does_not_exist_error_description())

    @staticmethod
    def signal_no_floors():
        raise RuntimeError(Hotel.no_floors_error_description())

    @staticmethod
    def signal_room_number_does_not_exist():
        raise RuntimeError(Hotel.room_number_does_not_exist_error_description())

